head.script:
(function(){
var NS="http://www.w3.org/1999/xhtml",d=document,def=Object.defineProperty;
var root=d.getElementsByTagName("foreignObject")[0].firstElementChild;
def(d,"head",{get:function(){return root.querySelector("head")},configurable:true});
def(d,"body",{get:function(){return root.querySelector("body")},configurable:true});
def(d,"documentElement",{get:function(){return root},configurable:true});
var ce=d.createElement.bind(d),cens=d.createElementNS.bind(d);
d.createElement=function(t,o){return typeof t==="string"?cens(NS,t,o):ce(t,o)};
d.createElementNS=function(ns,q,o){return cens(ns==null?NS:ns,q,o)};

// SVG is an XML document, but the app builds its settings panels with HTML
// strings. Parse those strings with the HTML parser, then import the resulting
// XHTML nodes into this document so void tags and text such as "Ice & Fire"
// do not throw XML SyntaxErrors.
var ep=Element.prototype,desc;
while(ep&&!desc){desc=Object.getOwnPropertyDescriptor(ep,"innerHTML");if(!desc)ep=Object.getPrototypeOf(ep);}
if(ep&&desc&&desc.configurable&&desc.get&&desc.set){
def(ep,"innerHTML",{
  configurable:true,
  enumerable:desc.enumerable,
  get:function(){return desc.get.call(this)},
  set:function(markup){
    if(this.namespaceURI!==NS){desc.set.call(this,markup);return;}
    var parsed=new DOMParser().parseFromString(String(markup),"text/html");
    while(this.firstChild)this.removeChild(this.firstChild);
    var nodes=parsed.body.childNodes;
    for(var i=0;i<nodes.length;i++)this.appendChild(d.importNode(nodes[i],true));
  }
});
}
})();

/* Theme presets. Everything (shell, homepage grid, island glow) reads these four colors. */
(function () {
	var P = {
		golden: { n: "Golden Hour", a: "#8f7cff", g1: "#8f7cff", g2: "#4f46e5", bg: "#0a0a12" },
		ocean: { n: "Ocean", a: "#38bdf8", g1: "#22d3ee", g2: "#2563eb", bg: "#050b14" },
		aurora: { n: "Aurora", a: "#34d399", g1: "#2dd4bf", g2: "#7c3aed", bg: "#04100d" },
		sakura: { n: "Sakura", a: "#f472b6", g1: "#fb7185", g2: "#c026d3", bg: "#140810" },
		ember: { n: "Ember", a: "#fb923c", g1: "#f97316", g2: "#dc2626", bg: "#120a06" },
		glacier: { n: "Glacier", a: "#a5b4fc", g1: "#93c5fd", g2: "#818cf8", bg: "#080a12" },
		mono: { n: "Mono", a: "#e5e7eb", g1: "#9ca3af", g2: "#4b5563", bg: "#0a0a0a" },
		cyber: { n: "Cyberpunk", a: "#f0abfc", g1: "#ec4899", g2: "#06b6d4", bg: "#100817" },
		neon: { n: "Neon City", a: "#a3ff12", g1: "#84cc16", g2: "#06b6d4", bg: "#07100b" },
		ruby: { n: "Ruby Night", a: "#fb7185", g1: "#e11d48", g2: "#7f1d1d", bg: "#12070d" },
		mint: { n: "Mint Chip", a: "#5eead4", g1: "#34d399", g2: "#0f766e", bg: "#04110f" },
		sunset: { n: "Afterglow", a: "#fda4af", g1: "#fb7185", g2: "#f59e0b", bg: "#17090e" },
		cosmic: { n: "Cosmic", a: "#c4b5fd", g1: "#7c3aed", g2: "#2563eb", bg: "#08071a" },
		forest: { n: "Deep Forest", a: "#86efac", g1: "#16a34a", g2: "#14532d", bg: "#06110a" },
		icefire: { n: "Ice & Fire", a: "#67e8f9", g1: "#0ea5e9", g2: "#f97316", bg: "#080d17" },
		ultraviolet: { n: "Ultraviolet", a: "#d8b4fe", g1: "#9333ea", g2: "#db2777", bg: "#10051a" },
	};
	var cur = "golden";
	try { cur = localStorage.getItem("mw-theme") || cur; } catch (e) {}
	if (!P[cur]) cur = "golden";

	function vars() {
		var p = P[cur];
		return { "--mw-accent": p.a, "--mw-g1": p.g1, "--mw-g2": p.g2, "--mw-bg": p.bg };
	}
	function set(id) {
		if (!P[id]) return;
		cur = id;
		var v = vars(), r = document.documentElement.style;
		for (var k in v) r.setProperty(k, v[k]);
		try { localStorage.setItem("mw-theme", id); } catch (e) {}
		window.dispatchEvent(new CustomEvent("mw-theme", { detail: id }));
		document.querySelectorAll(".mw-sw").forEach(function (b) {
			b.classList.toggle("on", b.dataset.id === id);
		});
	}
	/* hook your settings page into this: mwTheme.presets, mwTheme.set("ocean"), mwTheme.current */
	window.mwTheme = { presets: P, vars: vars, set: set, get current() { return cur; } };
	set(cur);

	})();

body.script:
(function(){
  var APP_KEY = "gETrNnD1k1FdEX3A_YGAcFHyuVxPPBPS";
  var TAG = "minason-web";
  var badge = document.getElementById("mw-active-users");
  var countNode = document.getElementById("mw-active-users-count");
  if (!badge || !countNode) return;

  var style = document.createElement("style");
  style.textContent = "#mw-active-users{position:fixed;left:16px;bottom:14px;z-index:2147483647;display:none;align-items:center;gap:8px;min-height:34px;padding:0 12px;border:1px solid rgba(255,255,255,.13);border-radius:999px;background:rgba(10,10,18,.68);backdrop-filter:blur(18px) saturate(160%);-webkit-backdrop-filter:blur(18px) saturate(160%);box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 5px 20px rgba(0,0,0,.18);color:#aaa8c4;font:650 10px/1 system-ui,sans-serif;pointer-events:none;user-select:none}#mw-active-users .mw-active-dot{width:7px;height:7px;flex:none;border-radius:50%;background:#85859a;box-shadow:0 0 8px rgba(133,133,154,.25)}#mw-active-users.is-ready .mw-active-dot{background:#39e8a4;box-shadow:0 0 10px rgba(57,232,164,.7)}#mw-active-users strong{color:#f2f0ff;font-size:11px;font-weight:900;font-variant-numeric:tabular-nums}#mw-active-users .mw-active-label{margin-left:-5px}@media(max-width:560px){#mw-active-users{left:10px;bottom:10px;min-height:31px;padding:0 10px;font-size:9px}}";
  document.head.appendChild(style);

  function syncHomeVisibility(){
    var input = document.getElementById("search");
    badge.style.display = input && !String(input.value || "").trim() ? "flex" : "none";
  }
  syncHomeVisibility();
  window.setInterval(syncHomeVisibility, 350);
  document.addEventListener("input", function(event){
    if (event.target && event.target.id === "search") syncHomeVisibility();
  }, true);

  function setCount(value){
    if (!Number.isFinite(Number(value))) return;
    countNode.textContent = String(Math.max(0, Math.floor(Number(value))));
    badge.classList.add("is-ready");
  }

  function connect(){
    var sdk = window.SimplePresence;
    if (sdk && sdk.SimplePresence) {
      try {
        var presence = new sdk.SimplePresence({
          tag: TAG,
          appKey: APP_KEY,
          onCountChange: setCount
        });
        setCount(presence.getCount());
        window.addEventListener("pagehide", function(){ presence.destroy(); }, {once:true});
        return;
      } catch (error) {
        console.warn("Minason Web presence could not start:", error);
      }
    }
    countNode.textContent = "—";
  }

  var script = document.createElement("script");
  script.src = "https://unpkg.com/@simple-presence/core@0.3.3";
  script.async = true;
  script.onload = connect;
  script.onerror = function(){ console.warn("Minason Web presence SDK failed to load."); };
  document.head.appendChild(script);
})();
